#!/usr/bin/env python3
"""Snake for the terminal, built on curses."""
import curses
import random
import time

DIRS = {curses.KEY_UP: (-1, 0), curses.KEY_DOWN: (1, 0), curses.KEY_LEFT: (0, -1), curses.KEY_RIGHT: (0, 1)}


def place_food(snake, h, w):
    while True:
        spot = (random.randrange(1, h - 1), random.randrange(1, w - 1))
        if spot not in snake:
            return spot


def play(stdscr):
    curses.curs_set(0)
    stdscr.nodelay(True)
    stdscr.timeout(90)
    h, w = stdscr.getmaxyx()
    snake = [(h // 2, w // 2 - i) for i in range(3)]
    heading = (0, 1)
    food = place_food(snake, h, w)
    score = 0
    while True:
        key = stdscr.getch()
        if key in DIRS:
            nxt = DIRS[key]
            if (nxt[0] + heading[0], nxt[1] + heading[1]) != (0, 0):
                heading = nxt
        elif key in (ord("q"), 27):
            return score
        head = (snake[0][0] + heading[0], snake[0][1] + heading[1])
        if head in snake or not (0 < head[0] < h - 1 and 0 < head[1] < w - 1):
            return score
        snake.insert(0, head)
        if head == food:
            score += 1
            food = place_food(snake, h, w)
        else:
            snake.pop()
        stdscr.erase()
        stdscr.border()
        stdscr.addstr(0, 2, f" score {score} ")
        stdscr.addch(*food, ord("*"))
        for y, x in snake:
            stdscr.addch(y, x, ord("#"))
        stdscr.refresh()


def main():
    score = curses.wrapper(play)
    print(f"Game over. Score: {score}")


if __name__ == "__main__":
    main()
